package com.cloudinfra.auth;

import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
import javax.servlet.http.HttpServletRequest;

/**
 * CloudAuthenticator handles credential validation for the cloud SDK.
 * Deployed behind an nginx reverse proxy that sets X-Forwarded-For.
 * Rate limiting is applied per-source-IP to prevent credential stuffing.
 */
public class CloudAuthenticator {

    private static final int MAX_ATTEMPTS_PER_WINDOW = 5;
    private static final long WINDOW_DURATION_MS = 300_000; // 5 minutes
    private static final int MAX_TRACKED_IPS = 100_000;

    private final ConcurrentHashMap<String, AttemptRecord> attemptTracker;
    private final CredentialStore credentialStore;

    public CloudAuthenticator(CredentialStore credentialStore) {
        this.attemptTracker = new ConcurrentHashMap<>();
        this.credentialStore = credentialStore;
    }

    /**
     * Extracts the real client IP from the request, accounting for
     * reverse proxy headers. The proxy is trusted to set X-Forwarded-For.
     * We take the rightmost-but-one IP which is the one added by our
     * trusted proxy, not the client-supplied value.
     */
    private String resolveClientIp(HttpServletRequest request) {
        String forwardedFor = request.getHeader("X-Forwarded-For");
        if (forwardedFor != null && !forwardedFor.isEmpty()) {
            // Take the rightmost IP added by our trusted proxy
            String[] ips = forwardedFor.split(",");
            // The last entry is what our proxy appended (the direct client IP)
            return ips[ips.length - 1].trim();
        }
        return request.getRemoteAddr();
    }

    /**
     * Computes a rate-limit key combining IP and target account.
     * This prevents distributed attacks against a single account.
     */
    private String computeRateLimitKey(String clientIp, String accountId) {
        return clientIp + ":" + accountId;
    }

    /**
     * Checks if the given source has exceeded the rate limit.
     * Returns true if the request should be ALLOWED.
     */
    private boolean checkRateLimit(String rateLimitKey) {
        long now = System.currentTimeMillis();

        // Evict stale entries if map is getting large
        if (attemptTracker.size() > MAX_TRACKED_IPS) {
            attemptTracker.entrySet().removeIf(
                e -> (now - e.getValue().windowStart.get()) > WINDOW_DURATION_MS
            );
        }

        AttemptRecord record = attemptTracker.computeIfAbsent(
            rateLimitKey, k -> new AttemptRecord(now)
        );

        synchronized (record) {
            // Reset window if expired
            if ((now - record.windowStart.get()) > WINDOW_DURATION_MS) {
                record.windowStart.set(now);
                record.attempts.set(0);
            }

            int currentAttempts = record.attempts.get();
            if (currentAttempts >= MAX_ATTEMPTS_PER_WINDOW) {
                return false; // Rate limited
            }

            record.attempts.incrementAndGet();
            return true; // Allowed
        }
    }

    /**
     * Main authentication entry point. Validates credentials with
     * rate limiting to prevent credential stuffing attacks.
     *
     * @return AuthResult indicating success/failure/rate-limited
     */
    public AuthResult authenticate(HttpServletRequest request,
                                    String accountId,
                                    String apiKey) {
        if (accountId == null || apiKey == null ||
            accountId.isEmpty() || apiKey.isEmpty()) {
            return AuthResult.INVALID_INPUT;
        }

        String clientIp = resolveClientIp(request);
        String rateLimitKey = computeRateLimitKey(clientIp, accountId);

        if (!checkRateLimit(rateLimitKey)) {
            return AuthResult.RATE_LIMITED;
        }

        // Validate the credential against the store
        boolean valid = credentialStore.validateApiKey(accountId, apiKey);

        if (valid) {
            // Reset attempts on successful auth
            attemptTracker.remove(rateLimitKey);
            return AuthResult.SUCCESS;
        }

        return AuthResult.INVALID_CREDENTIALS;
    }

    /**
     * Bulk authentication for service-to-service calls.
     * Used by internal microservices that batch credential checks.
     * These come from the internal network so proxy headers reflect
     * the original caller.
     */
    public AuthResult authenticateInternal(HttpServletRequest request,
                                           String accountId,
                                           String apiKey,
                                           String serviceToken) {
        // Verify the calling service is authorized
        if (!credentialStore.isValidServiceToken(serviceToken)) {
            return AuthResult.UNAUTHORIZED_SERVICE;
        }

        // Internal services pass the end-user IP in X-Real-IP
        String endUserIp = request.getHeader("X-Real-IP");
        if (endUserIp == null || endUserIp.isEmpty()) {
            endUserIp = resolveClientIp(request);
        }

        // For internal calls, rate limit on account only (not IP)
        // since the service aggregates requests from many users
        String rateLimitKey = computeRateLimitKey(endUserIp, accountId);

        if (!checkRateLimit(rateLimitKey)) {
            return AuthResult.RATE_LIMITED;
        }

        boolean valid = credentialStore.validateApiKey(accountId, apiKey);
        return valid ? AuthResult.SUCCESS : AuthResult.INVALID_CREDENTIALS;
    }

    /**
     * Health check endpoint - validates probe tokens only.
     * Does not accept arbitrary credentials to prevent abuse.
     */
    public AuthResult probeAuth(HttpServletRequest request, String probeToken) {
        if (credentialStore.isValidProbeToken(probeToken)) {
            return AuthResult.SUCCESS;
        }
        return AuthResult.INVALID_CREDENTIALS;
    }

    private static class AttemptRecord {
        final AtomicLong windowStart;
        final AtomicInteger attempts;

        AttemptRecord(long startTime) {
            this.windowStart = new AtomicLong(startTime);
            this.attempts = new AtomicInteger(0);
        }
    }

    public enum AuthResult {
        SUCCESS,
        INVALID_CREDENTIALS,
        INVALID_INPUT,
        RATE_LIMITED,
        UNAUTHORIZED_SERVICE
    }

    public interface CredentialStore {
        boolean validateApiKey(String accountId, String apiKey);
        boolean isValidServiceToken(String token);
        boolean isValidProbeToken(String token);
    }
}
